INSERT INTO prof VALUES
  (8937, $$Journal du Gabon$$, 'GA', $$Yogam Group SAS (société privée de droit français, Paris)$$, $$Yogam Group SAS ; directeur de publication Cyrille T. Nono, fondateur de la régie Cynomedia et éditeur de Journal du Cameroun$$, ARRAY['commercial_generalist']::text[], NULL, $$Déclinaison gabonaise du réseau de sites « Journal du/de … » né autour de Journal du Cameroun (2008). La régie Cynomedia Africa, fondée par Cyrille T. Nono, commercialise en exclusivité les espaces publicitaires des quinze sites du réseau.$$, $$Site d’information générale sur l’actualité gabonaise (politique, économie, société, sport), édité depuis Paris. Aucune affiliation gouvernementale ou partisane documentée dans les sources consultées ; aucune étude indépendante de sa ligne éditoriale trouvée.$$, 'medium', $$Éditeur et directeur de publication identifiés par les mentions légales du site (consultées le 2026-10-16) et par la page de la régie Cynomedia ; ligne éditoriale non évaluée par une source indépendante.$$, $$[{"url": "https://www.journaldugabon.com/mentions-legales", "note": "Mentions légales : éditeur Yogam Group SAS (RCS Paris 102 832 623), directeur de publication Cyrille T. Nono", "category": "self_described", "accessed_at": "2026-10-16"}, {"url": "https://cynomedia.com/expertises/edition/", "note": "Cynomedia Africa gère en exclusivité les espaces publicitaires d’un réseau de quinze sites « Journal du/de … » (Cameroun, Tchad, Gabon, Kinshasa, Brazza, Bangui, Malabo, Mali, Niger, Conakry, Abidjan, Faso, Sénégal, Bénin, Togo)", "category": "self_described", "accessed_at": "2026-10-16"}, {"url": "https://cameroonceo.com/2017/08/21/cyrille-tchuente-nono-ceo-cynomedia-groupe-une-etoile-camerounaise-du-web-panafricain/", "note": "Cyrille Tchuente Nono, fondateur de Cynomedia (2003) ; YOGAM, entité de Cynomedia, édite journalducameroun.com", "category": "press", "accessed_at": "2026-10-16"}]$$::jsonb, false),
