  (8948, $$Journal d'Abidjan$$, 'CI', $$Yogam Group SAS (société privée de droit français, Paris)$$, $$Yogam Group SAS ; directeur de publication Cyrille T. Nono, fondateur de la régie Cynomedia et éditeur de Journal du Cameroun$$, ARRAY['commercial_generalist']::text[], NULL, $$Déclinaison ivoirienne du réseau de sites « Journal du/de … » né autour de Journal du Cameroun (2008). La régie Cynomedia Africa, fondée par Cyrille T. Nono, commercialise en exclusivité les espaces publicitaires des quinze sites du réseau. Wikipédia attribue ce site à Impact Média Presse, éditeur de Journal du Mali ; les mentions légales actuelles désignent Yogam Group SAS.$$, $$Site d’information générale sur l’actualité ivoirienne (politique, économie, société, sport), édité depuis Paris. Aucune affiliation gouvernementale ou partisane documentée dans les sources consultées ; aucune étude indépendante de sa ligne éditoriale trouvée.$$, 'medium', $$Éditeur et directeur de publication identifiés par les mentions légales du site (consultées le 2026-10-16) et par la page de la régie Cynomedia ; ligne éditoriale non évaluée par une source indépendante. Attribution contradictoire à vérifier (voir contexte historique).$$, $$[{"url": "https://www.journaldabidjan.com/mentions-legales", "note": "Mentions légales : éditeur Yogam Group SAS (RCS Paris 102 832 623), directeur de publication Cyrille T. Nono", "category": "self_described", "accessed_at": "2026-10-16"}, {"url": "https://cynomedia.com/expertises/edition/", "note": "Cynomedia Africa gère en exclusivité les espaces publicitaires d’un réseau de quinze sites « Journal du/de … » (Cameroun, Tchad, Gabon, Kinshasa, Brazza, Bangui, Malabo, Mali, Niger, Conakry, Abidjan, Faso, Sénégal, Bénin, Togo)", "category": "self_described", "accessed_at": "2026-10-16"}, {"url": "https://cameroonceo.com/2017/08/21/cyrille-tchuente-nono-ceo-cynomedia-groupe-une-etoile-camerounaise-du-web-panafricain/", "note": "Cyrille Tchuente Nono, fondateur de Cynomedia (2003) ; YOGAM, entité de Cynomedia, édite journalducameroun.com", "category": "press", "accessed_at": "2026-10-16"}, {"url": "https://en.wikipedia.org/wiki/Le_Journal_du_Mali", "note": "Attribue à Impact Média Presse, éditeur de Journal du Mali, d’autres sites du réseau dont Journal du Faso et Journal d’Abidjan", "category": "reference", "accessed_at": "2026-10-16"}]$$::jsonb, true),
  (8963, $$People 243$$, 'CD', $$Yogam Group SAS (société privée de droit français, Paris)$$, $$Yogam Group SAS ; directeur de publication Cyrille T. Nono, fondateur de la régie Cynomedia et éditeur de Journal du Cameroun$$, ARRAY['specialist']::text[], NULL, $$Site « people » du même éditeur que le réseau « Journal du/de … » ; Yogam publie des sites people dans plusieurs pays (People237, People225, People228…).$$, $$Actualité des célébrités, de la musique et du divertissement en République démocratique du Congo ; pas de couverture politique suivie. Aucune affiliation gouvernementale ou partisane documentée.$$, 'medium', $$Éditeur et directeur de publication identifiés par les mentions légales du site (consultées le 2026-10-16) et par la page de la régie Cynomedia ; ligne éditoriale non évaluée par une source indépendante.$$, $$[{"url": "https://www.people243.com/mentions-legales", "note": "Mentions légales : éditeur Yogam Group SAS, directeur de publication Cyrille T. Nono", "category": "self_described", "accessed_at": "2026-10-16"}, {"url": "https://cameroonceo.com/2017/08/21/cyrille-tchuente-nono-ceo-cynomedia-groupe-une-etoile-camerounaise-du-web-panafricain/", "note": "Cyrille Tchuente Nono, fondateur de Cynomedia (2003) ; YOGAM, entité de Cynomedia, édite journalducameroun.com", "category": "press", "accessed_at": "2026-10-16"}]$$::jsonb, false),
  (8940, $$Journal du Mali$$, 'ML', $$Impact Média Presse SARL (société privée malienne, Bamako)$$, $$Mahamadou Camara (fondateur et directeur de publication), ancien directeur de cabinet du président Ibrahim Boubacar Keïta et ancien ministre de l’Économie numérique, de l’Information et de la Communication (2014-2015)$$, ARRAY['commercial_generalist']::text[], NULL, $$Site lancé en 2009 par Mahamadou Camara, également fondateur de l’agence Impact Media Conseil et de la régie d’affichage MIP Mali ; hebdomadaire imprimé lancé en 2015. Le fondateur a été directeur de cabinet du président Keïta puis ministre de la Communication (2014-2015).$$, $$Site d’information générale et hebdomadaire, dont la régie Cynomedia Africa commercialise les espaces publicitaires. Mahamadou Camara a été placé en détention en mars 2020 puis en septembre 2021 dans l’affaire de l’avion présidentiel et des équipements militaires achetés en 2014 ; l’issue judiciaire n’a pas été vérifiée. Aucune étude indépendante de la ligne éditoriale actuelle trouvée.$$, 'medium', $$Éditeur et directeur de publication identifiés par les mentions légales et Wikipédia ; parcours politique et poursuites du fondateur documentés par Wikipédia et l’Agence Anadolu ; ligne éditoriale actuelle non évaluée.$$, $$[{"url": "https://www.journaldumali.com/mentions-legales", "note": "Mentions légales : éditeur Impact Média Presse (Bamako), directeur de publication Mahamadou Camara", "category": "self_described", "accessed_at": "2026-10-16"}, {"url": "https://en.wikipedia.org/wiki/Le_Journal_du_Mali", "note": "Propriété d’Impact Média Presse SARL, fondée par Mahamadou Camara (2009)", "category": "reference", "accessed_at": "2026-10-16"}, {"url": "https://fr.wikipedia.org/wiki/Mahamadou_Camara", "note": "Ancien directeur de cabinet du président et ministre (2014-2015) ; fondateur de journaldumali.com, Impact Media Conseil et MIP Mali", "category": "reference", "accessed_at": "2026-10-16"}, {"url": "https://www.aa.com.tr/fr/afrique/mali-lancien-ministre-de-la-communication-mahamadou-camara-d%C3%A9f%C3%A9r%C3%A9-en-prison/2373458", "note": "Placé en détention le 23 septembre 2021 (complicité de favoritisme, affaire de l’avion présidentiel)", "category": "press", "accessed_at": "2026-10-16"}, {"url": "https://cynomedia.com/expertises/edition/", "note": "Cynomedia Africa gère en exclusivité les espaces publicitaires d’un réseau de quinze sites « Journal du/de … » (Cameroun, Tchad, Gabon, Kinshasa, Brazza, Bangui, Malabo, Mali, Niger, Conakry, Abidjan, Faso, Sénégal, Bénin, Togo)", "category": "self_described", "accessed_at": "2026-10-16"}]$$::jsonb, true);
DO $$
DECLARE bad int; n int;
BEGIN
  -- Each target must be the active publisher of that name in that country, and must not have a profile yet.
  SELECT count(*) INTO bad FROM prof x
   WHERE NOT EXISTS (SELECT 1 FROM publishers p JOIN countries c ON c.id = p.country_id
                      WHERE p.id = x.publisher_id AND p.name = x.name AND c.iso_code = x.iso AND p.feed_status = 'active')
      OR EXISTS (SELECT 1 FROM editorial_profiles e WHERE e.publisher_id = x.publisher_id);
  IF bad > 0 THEN RAISE EXCEPTION '% of 13 publishers are not the expected outlet or already have a profile - nothing changed', bad; END IF;
  INSERT INTO editorial_profiles (publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, classification_date, last_reviewed, evidence_date, review_required)
  SELECT publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, DATE '2026-10-16', DATE '2026-10-16', DATE '2026-10-16', review_required FROM prof;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 13 THEN RAISE EXCEPTION 'inserted %, expected 13', n; END IF;
END $$;
SELECT 'profile|' || p.id || '|' || p.name || '|' || array_to_string(e.classification_tags, ',') || '|' || e.confidence || '|review ' || e.review_required
       || '|' || jsonb_array_length(e.evidence_sources) || ' sources'
  FROM editorial_profiles e JOIN publishers p ON p.id = e.publisher_id WHERE e.publisher_id IN (8937, 8938, 8939, 8941, 8942, 8943, 8944, 8945, 8946, 8947, 8948, 8963, 8940) ORDER BY p.id;
SELECT 'gap|' || count(*) || ' active publishers still without a profile'
  FROM publishers p LEFT JOIN editorial_profiles e ON e.publisher_id = p.id WHERE p.feed_status = 'active' AND e.id IS NULL;
COMMIT;
